*** Begin Patch
*** Add File: /private/var/folders/0q/2rdtymtx2yvgjq38pr1pm2lc0000gn/T/opencode-skill-state-one-shot/20260904T023009Z/baseline/taskboard-cli/src/cli.ts
+type Status = "open" | "done";
+
+interface Task {
+  id: number;
+  title: string;
+  tags: string[];
+  status: Status;
+  createdAt: string;
+  due?: string;
+  completedAt?: string;
+}
+
+interface Database {
+  tasks: Task[];
+}
+
+const databasePath = process.env.TASKBOARD_FILE || ".taskboard.json";
+
+function fail(message: string): never {
+  console.error(message);
+  process.exit(1);
+}
+
+function isDate(value: string): boolean {
+  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
+  const [year, month, day] = value.split("-").map(Number);
+  const date = new Date(Date.UTC(year, month - 1, day));
+  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
+}
+
+function todayLocal(): string {
+  const now = new Date();
+  const year = now.getFullYear();
+  const month = String(now.getMonth() + 1).padStart(2, "0");
+  const day = String(now.getDate()).padStart(2, "0");
+  return `${year}-${month}-${day}`;
+}
+
+function loadDatabase(): Database {
+  const file = Bun.file(databasePath);
+  if (!file.exists()) return { tasks: [] };
+
+  let parsed: unknown;
+  try {
+    parsed = JSON.parse(Bun.file(databasePath).textSync());
+  } catch {
+    fail(`Malformed taskboard database: ${databasePath}`);
+  }
+
+  if (!isDatabase(parsed)) fail(`Malformed taskboard database: ${databasePath}`);
+  return parsed;
+}
+
+function isDatabase(value: unknown): value is Database {
+  if (!value || typeof value !== "object" || !Array.isArray((value as Database).tasks)) return false;
+  const ids = new Set<number>();
+  return (value as Database).tasks.every((task) => {
+    if (!task || typeof task !== "object") return false;
+    const candidate = task as Task;
+    if (!Number.isSafeInteger(candidate.id) || candidate.id < 1 || ids.has(candidate.id)) return false;
+    ids.add(candidate.id);
+    return typeof candidate.title === "string"
+      && Array.isArray(candidate.tags)
+      && candidate.tags.every((tag) => typeof tag === "string")
+      && (candidate.status === "open" || candidate.status === "done")
+      && typeof candidate.createdAt === "string"
+      && (candidate.due === undefined || (typeof candidate.due === "string" && isDate(candidate.due)))
+      && (candidate.completedAt === undefined || typeof candidate.completedAt === "string");
+  });
+}
+
+function saveDatabase(database: Database): void {
+  const temporaryPath = `${databasePath}.${process.pid}.${Date.now()}.tmp`;
+  try {
+    Bun.write(temporaryPath, `${JSON.stringify(database, null, 2)}\n`);
+    Bun.spawnSync(["mv", "-f", temporaryPath, databasePath]);
+  } catch (error) {
+    try { Bun.spawnSync(["rm", "-f", temporaryPath]); } catch { /* Best-effort cleanup. */ }
+    fail(`Unable to save taskboard database: ${error instanceof Error ? error.message : String(error)}`);
+  }
+}
+
+function parseOptions(args: string[], allowed: readonly string[]): Map<string, string> {
+  const options = new Map<string, string>();
+  for (let index = 0; index < args.length; index += 2) {
+    const flag = args[index];
+    const value = args[index + 1];
+    if (!flag?.startsWith("--") || !allowed.includes(flag) || value === undefined || options.has(flag)) {
+      fail("Invalid command arguments");
+    }
+    options.set(flag, value);
+  }
+  return options;
+}
+
+function parseId(value: string | undefined): number {
+  if (!value || !/^\d+$/.test(value)) fail("Task ID must be a positive integer");
+  const id = Number(value);
+  if (!Number.isSafeInteger(id) || id < 1) fail("Task ID must be a positive integer");
+  return id;
+}
+
+function normalizedTags(value: string | undefined): string[] {
+  if (!value) return [];
+  const tags = value.split(",").map((tag) => tag.trim().toLowerCase());
+  if (tags.some((tag) => !tag)) fail("Tags must not be empty");
+  return [...new Set(tags)];
+}
+
+function print(value: unknown): void {
+  console.log(JSON.stringify(value));
+}
+
+const [command, ...args] = Bun.argv.slice(2);
+const database = loadDatabase();
+
+switch (command) {
+  case "add": {
+    const options = parseOptions(args, ["--title", "--tags", "--due"]);
+    const title = options.get("--title")?.trim();
+    const due = options.get("--due");
+    if (!title) fail("Title must not be empty");
+    if (due !== undefined && !isDate(due)) fail("Due date must be a valid YYYY-MM-DD date");
+    const id = database.tasks.reduce((maximum, task) => Math.max(maximum, task.id), 0) + 1;
+    const task: Task = { id, title, tags: normalizedTags(options.get("--tags")), status: "open", createdAt: new Date().toISOString() };
+    if (due !== undefined) task.due = due;
+    database.tasks.push(task);
+    saveDatabase(database);
+    print(task);
+    break;
+  }
+  case "list": {
+    const options = parseOptions(args, ["--status", "--tag", "--overdue"]);
+    const status = options.get("--status");
+    const tag = options.get("--tag")?.trim().toLowerCase();
+    const overdue = options.get("--overdue");
+    if (status !== undefined && status !== "open" && status !== "done") fail("Status must be open or done");
+    if (tag !== undefined && !tag) fail("Tag must not be empty");
+    if (overdue !== undefined && !isDate(overdue)) fail("Overdue date must be a valid YYYY-MM-DD date");
+    print(database.tasks.filter((task) =>
+      (status === undefined || task.status === status)
+      && (tag === undefined || task.tags.includes(tag))
+      && (overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue)),
+    ).sort((left, right) => left.id - right.id));
+    break;
+  }
+  case "done": {
+    if (args.length !== 1) fail("Usage: done ID");
+    const task = database.tasks.find((candidate) => candidate.id === parseId(args[0]));
+    if (!task) fail("Task not found");
+    if (task.status !== "done") {
+      task.status = "done";
+      task.completedAt = new Date().toISOString();
+      saveDatabase(database);
+    }
+    print(task);
+    break;
+  }
+  case "delete": {
+    if (args.length !== 1) fail("Usage: delete ID");
+    const id = parseId(args[0]);
+    const index = database.tasks.findIndex((task) => task.id === id);
+    if (index === -1) fail("Task not found");
+    const [task] = database.tasks.splice(index, 1);
+    saveDatabase(database);
+    print(task);
+    break;
+  }
+  case "stats": {
+    if (args.length !== 0) fail("Usage: stats");
+    const today = todayLocal();
+    const open = database.tasks.filter((task) => task.status === "open");
+    print({ total: database.tasks.length, open: open.length, done: database.tasks.length - open.length, overdue: open.filter((task) => task.due !== undefined && task.due < today).length });
+    break;
+  }
+  default:
+    fail("Unknown command");
+}
